package ama.transcript;
import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static ama.transcript.Task11ClosedHistoryFixture.*;
/** Real complete-history SQL acquisition and canonical verification; only JDBC/ACL are substituted. */
class Task11ClosedHistoryGuardTest {
 @Test void genuineGuardAdmitsCompleteLocalAndRemoteHistoryWithoutChangingOriginals()throws Exception{for(boolean remote:List.of(false,true)){var h=remote?new Fixture().remote():new Fixture().local();var f=sql(h,new AtomicBoolean());var original=Map.copyOf(h.originals);var p=f.prepare();f.tx.required(()->{var held=f.guard.controls(p,Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING,f.root);f.guard.tasks(held,f.root);f.guard.requirePermitted(held,f.root);f.guard.claim(held,f.root);return null;});assertEquals(original,h.originals);assertTrue(f.updates.isEmpty());}}
 @Test void sameLengthOriginalChangeAtFinalReadIsRejectedWithoutClaimOrWrite()throws Exception{var h=new Fixture().remote();var changed=new AtomicBoolean();var f=sql(h,changed);var p=f.prepare();changed.set(true);var failure=assertThrows(ama.contract.MinutesContracts.Failure.class,()->f.tx.required(()->{var held=f.guard.controls(p,Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING,f.root);f.guard.tasks(held,f.root);f.guard.requirePermitted(held,f.root);return null;}));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,failure.code());assertTrue(f.updates.isEmpty());}
 @Test void failedHeaderWithOlderUnknownCannotAcquireWritePermission()throws Exception{var h=new Fixture().remote();h.rows.get("external_execution").getFirst().put("state","UNKNOWN");var f=sql(h,new AtomicBoolean());var p=f.prepare();assertThrows(ama.contract.MinutesContracts.Failure.class,()->f.tx.required(()->{var held=f.guard.controls(p,Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING,f.root);f.guard.tasks(held,f.root);f.guard.claim(held,f.root);return null;}));assertTrue(f.updates.isEmpty());}
 @Test void originalTransferRequiresFreshOwnerAndAllHistoryLocks()throws Exception{
  var f=sql(new Fixture().remote(),new AtomicBoolean());var authorized=new AtomicBoolean();
  org.mockito.Mockito.when(f.access.lock(Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING)).thenReturn(f.root);
  org.mockito.Mockito.doAnswer(x->{assertTrue(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());authorized.set(true);return null;}).when(f.access).require(f.root,ama.access.MeetingAccess.Action.EDIT);
  var response=f.responder;f.responder=q->{if(q.startsWith("SELECT request_manifest")){assertTrue(authorized.get(),"original before fresh owner authorization");assertTrue(q.endsWith("FOR UPDATE"));for(String table:List.of("publication","final_confirmation","publication_submission","durable_task","task_attempt","external_operation","external_execution"))assertTrue(f.sql.stream().anyMatch(x->x.contains(" FROM "+table+" ")&&x.endsWith("FOR UPDATE")),table+" missing protected S lock");}return response.apply(q);};
  f.prepare();assertTrue(authorized.get());
 }
 @Test void deniedOwnerNeverTransfersAnOriginal()throws Exception{
  var f=sql(new Fixture().remote(),new AtomicBoolean());org.mockito.Mockito.when(f.access.lock(Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING)).thenReturn(f.root);org.mockito.Mockito.doThrow(new ama.access.MeetingAccess.AccessDeniedException()).when(f.access).require(f.root,ama.access.MeetingAccess.Action.EDIT);
  var p=f.prepare();assertTrue(f.sql.stream().noneMatch(q->q.startsWith("SELECT request_manifest")),"denied original crossed JDBC");
  assertThrows(ama.access.MeetingAccess.AccessDeniedException.class,()->f.tx.required(()->{var h=f.guard.controls(p,Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING,f.root);f.guard.tasks(h,f.root);f.guard.claim(h,f.root);return null;}));
 }
 @Test void workerPreparationReleasesItsSeparateCaptureHolderBeforeAnalysis()throws Exception{
  var f=sql(new Fixture().remote(),new AtomicBoolean());org.mockito.Mockito.when(f.access.lock(Task11PublicationWriteGuardBoundaryTest.ACTOR,MEETING)).thenReturn(f.root);
  f.tx.required(()->{var outer=org.springframework.transaction.support.TransactionSynchronizationManager.getResource(f.ds);var response=f.responder;f.responder=q->{if(q.startsWith("SELECT request_manifest"))assertNotSame(outer,org.springframework.transaction.support.TransactionSynchronizationManager.getResource(f.ds),"S must release locks before detached analysis");return response.apply(q);};f.prepare();assertSame(outer,org.springframework.transaction.support.TransactionSynchronizationManager.getResource(f.ds));assertEquals(1,f.commits.get());return null;});
 }
 static Task11PublicationWriteGuardBoundaryTest.Fixture sql(Fixture history,AtomicBoolean changed)throws Exception{
  var f=new Task11PublicationWriteGuardBoundaryTest.Fixture();for(var row:history.rows.get("publication_submission")){String original=history.originals.get(row.get("task_id"));row.put("request_manifest_bytes",(long)original.length());row.put("request_manifest_scalars",(long)original.length());row.put("request_manifest_utf16",(long)original.length());}for(var row:history.rows.get("external_execution"))row.put("request_manifest_bytes",(long)history.originals.get(row.get("task_id")).length());
  f.responder=sql->{
   if(sql.startsWith("SELECT request_manifest FROM publication_submission")){String original=history.originals.get(TASK);if(changed.get()&&sql.endsWith("FOR UPDATE"))original=original.replace("owner","ownez");return List.of(Map.of("request_manifest",original));}
   if(sql.startsWith("SELECT OCTET_LENGTH(request_manifest) mb")){var original=history.executions.get(EXEC);long m=original.manifest().length(),e=original.noEffectEvidence().length();return List.of(row("mb",m,"ms",m,"mu",m,"eb",e,"es",e,"eu",e));}
   if(sql.startsWith("SELECT request_manifest,no_effect_evidence")){var original=history.executions.get(EXEC);return List.of(row("request_manifest",original.manifest(),"no_effect_evidence",original.noEffectEvidence()));}
   var match=java.util.regex.Pattern.compile("FROM ([a-z_]+) ").matcher(sql);if(!match.find())return null;String table=match.group(1);List<Map<String,Object>> rows=switch(table){case "meeting"->List.of(history.root);case "publication"->history.pubs;case "final_confirmation"->history.finals;default->history.rows.get(table);};if(rows==null)return null;if(sql.startsWith("SELECT COUNT(*)"))return List.of(Map.of("count",(long)rows.size()));return rows;
  };return f;
 }
}
